//! Declarations, types, and zero values — one language rule per test.

go_run_cases! {
    zero_value_int => ("package main; import \"fmt\"; func main() { var n int; fmt.Println(n) }", vec!["0"]),
    zero_value_bool => ("package main; import \"fmt\"; func main() { var b bool; fmt.Println(b) }", vec!["false"]),
    zero_value_string => ("package main; import \"fmt\"; func main() { var s string; fmt.Println(s == \"\") }", vec!["true"]),
    zero_value_pointer_nil => ("package main; import \"fmt\"; func main() { var p *int; fmt.Println(p == nil) }", vec!["true"]),
    zero_value_slice_nil => ("package main; import \"fmt\"; func main() { var s []int; fmt.Println(s == nil) }", vec!["true"]),
    zero_value_map_nil => ("package main; import \"fmt\"; func main() { var m map[int]int; fmt.Println(m == nil) }", vec!["true"]),
    zero_value_chan_nil => ("package main; import \"fmt\"; func main() { var ch chan int; fmt.Println(ch == nil) }", vec!["true"]),
    zero_value_func_nil => ("package main; import \"fmt\"; func main() { var f func(); fmt.Println(f == nil) }", vec!["true"]),
    zero_value_interface_nil => ("package main; import \"fmt\"; func main() { var i interface{}; fmt.Println(i == nil) }", vec!["true"]),
    const_arithmetic => ("package main; import \"fmt\"; const x = 10 * 5; func main() { fmt.Println(x) }", vec!["50"]),
    const_typed_vs_untyped => ("package main; import \"fmt\"; const x int = 3; func main() { fmt.Println(x) }", vec!["3"]),
    var_block_declaration => ("package main; import \"fmt\"; var ( a = 1; b = 2 ); func main() { fmt.Println(a + b) }", vec!["3"]),
    struct_equality => ("package main; import \"fmt\"; type P struct { X int }; func main() { fmt.Println(P{1} == P{1}) }", vec!["true"]),
    array_equality => ("package main; import \"fmt\"; func main() { fmt.Println([2]int{1,2} == [2]int{1,2}) }", vec!["true"]),
    string_to_bytes => ("package main; import \"fmt\"; func main() { b := []byte(\"go\"); fmt.Println(len(b)) }", vec!["2"]),
    bytes_to_string => ("package main; import \"fmt\"; func main() { s := string([]byte{97}); fmt.Println(s) }", vec!["a"]),
    int_to_string_conversion => ("package main; import \"fmt\"; func main() { s := fmt.Sprint(42); fmt.Println(s) }", vec!["42"]),
    rune_as_int => ("package main; import \"fmt\"; func main() { var r rune = 'Z'; fmt.Println(int(r)) }", vec!["90"]),
    underlying_type_conversion => ("package main; import \"fmt\"; type MyInt int; func main() { var m MyInt = 3; fmt.Println(int(m)) }", vec!["3"]),
    string_index_mutation_illegal_use_byte_slice => ("package main; import \"fmt\"; func main() { b := []byte(\"ab\"); b[0] = 'x'; fmt.Println(string(b)) }", vec!["xb"]),
    slice_reslice_capacity => ("package main; import \"fmt\"; func main() { s := make([]int, 2, 4); t := s[:3]; fmt.Println(cap(t)) }", vec!["4"]),
    three_index_slice => ("package main; import \"fmt\"; func main() { s := []int{0,1,2,3,4}; t := s[1:3:4]; fmt.Println(len(t), cap(t)) }", vec!["2 3"]),
    map_comma_ok_zero_value => ("package main; import \"fmt\"; func main() { m := map[string]int{\"a\":0}; v, ok := m[\"a\"]; fmt.Println(v, ok) }", vec!["0 true"]),
    struct_field_exported => ("package main; import \"fmt\"; type P struct { X int }; func main() { fmt.Println(P{X:1}.X) }", vec!["1"]),
    nested_anonymous_struct => ("package main; import \"fmt\"; func main() { v := struct{ N int }{N: 8}; fmt.Println(v.N) }", vec!["8"]),
    function_type_nil_eq => ("package main; import \"fmt\"; func main() { var f func(int) int; fmt.Println(f == nil) }", vec!["true"]),
    channel_eq_nil => ("package main; import \"fmt\"; func main() { var ch chan int; fmt.Println(ch == nil) }", vec!["true"]),
    comparable_array_as_map_key => ("package main; import \"fmt\"; func main() { m := map[[1]int]string{[1]int{1}:\"a\"}; fmt.Println(m[[1]int{1}]) }", vec!["a"]),
    type_switch_on_interface => ("package main; import \"fmt\"; func main() { switch any(\"x\").(type) { case string: fmt.Println(\"s\"); default: fmt.Println(\"d\") } }", vec!["s"]),
    labeled_for_break => ("package main; import \"fmt\"; func main() { L: for i := 0; i < 3; i++ { if i == 1 { break L }; fmt.Println(i) } }", vec!["0"]),
    labeled_for_continue => ("package main; import \"fmt\"; func main() { L: for i := 0; i < 3; i++ { if i == 1 { continue L }; fmt.Println(i) } }", vec!["0", "2"]),
    range_over_int_go122 => ("package main; import \"fmt\"; func main() { n := 0; for i := range 3 { n += i }; fmt.Println(n) }", vec!["3"]),
    import_alias => ("package main; import f \"fmt\"; func main() { f.Println(1) }", vec!["1"]),
    package_level_init_expr => ("package main; import \"fmt\"; var n = len([]int{1,2,3}); func main() { fmt.Println(n) }", vec!["3"]),
}

go_compile_cases! {
    slice_not_comparable_compile => "package main; func main() { _ = []int{1} == []int{1} }",
    map_not_comparable_compile => "package main; func main() { _ = map[int]int{} == map[int]int{} }",
    func_not_comparable_compile => "package main; func f() {}; func g() {}; func main() { _ = f == g }",
    struct_with_unexported_field_eq => "package main; type t struct { x int }; func main() { _ = t{} == t{} }",
    uintptr_convert_compile => "package main; import \"unsafe\"; func main() { var p *int; _ = uintptr(unsafe.Pointer(p)) }",
    array_pointer_index => "package main; func main() { a := [2]int{1,2}; p := &a; _ = (*p)[1] }",
    struct_tag_access_reflect_compile => "package main; import \"reflect\"; type S struct { X int `json:\"x\"` }; func main() { _ = reflect.TypeOf(S{}).Field(0).Tag }",
    dot_import_compile => "package main; import . \"fmt\"; func main() { Println(1) }",
    empty_struct_size_compile => "package main; import \"unsafe\"; type E struct{}; func main() { _ = unsafe.Sizeof(E{}) }",
    recursive_struct_via_pointer => "package main; type Node struct { Next *Node }; func main() { _ = Node{} }",
}
